  un('rs_instagram', 'Instagram: Reels, carruseles e historias', 'redes_eng', ['La cuenta profesional (de creador o de empresa) da acceso a estadísticas, botones de contacto y herramientas de venta.', 'Los Reels buscan alcance, los carruseles enseñan y las historias mantienen la relación diaria con quien ya te sigue.', 'Los destacados del perfil funcionan como un menú: precios, opiniones, preguntas frecuentes.', 'Instagram no reparte de forma general ingresos por anuncios: se gana con marcas, afiliación, suscripciones y ventas propias.', 'Las colaboraciones pagadas deben llevar la etiqueta de colaboración pagada o un aviso claro.'], ['cuenta profesional', 'Reels', 'historias', 'destacados', 'colaboración pagada'], 'V:La cuenta profesional da estadísticas.|F:Instagram paga a todos los creadores por sus vistas.|V:Las colaboraciones pagadas deben indicarse.', ['Organiza los destacados de un perfil de negocio.', 'Calcula la tasa de interacción de tres publicaciones.'], { t: 'mapa', c: 'Instagram', r: ['Reels: alcance', 'carrusel: enseñar', 'historias: relación', 'destacados: menú', 'mensajes: venta'] }, '¿Qué miras primero cuando entras en un perfil?', ['rs_pasos:ig']);
  un('rs_tiktok', 'TikTok: vídeo corto y Creator Rewards', 'redes_cpm', ['TikTok muestra los vídeos a personas que no te siguen: una cuenta nueva puede llegar a miles de personas con un solo vídeo.', 'El Programa Creator Rewards exige 18 años, cuenta personal, 10.000 seguidores y 100.000 visualizaciones en los últimos 30 días.', 'Solo pagan los vídeos originales de más de un minuto, y el programa está disponible en algunos países, entre ellos México y Estados Unidos.', 'La inscripción se hace desde el perfil: menú, TikTok Studio y Programa Creator Rewards; la respuesta llega en unos tres días.', 'TikTok no publica una tarifa fija por vista: el pago depende de la calidad, la originalidad y la región.'], ['Para ti', 'Creator Rewards', 'TikTok Studio', 'visualización cualificada', 'retención'], 'V:TikTok muestra vídeos a quien no te sigue.|F:Todos los vídeos cortos cobran en Creator Rewards.|V:Hacen falta 10.000 seguidores.', ['¿Cuáles son los requisitos del programa Creator Rewards?', 'Calcula lo que se ganaría con 200.000 vistas a un RPM de ejemplo.'], { t: 'flujo', p: ['publicar', 'retener', 'Para ti', 'seguidores', 'monetizar'] }, '¿Por qué un vídeo de alguien desconocido te aparece en TikTok?', ['rs_pasos:tiktok', 'rs_plataformas']);
  un('rs_telegram', 'Telegram y WhatsApp: canales y comunidades', 'redes_tg', ['Un canal envía mensajes a muchas personas a la vez; un grupo permite que todos conversen.', 'En Telegram los canales públicos con 1.000 suscriptores o más pueden recibir el 50 % de lo que Telegram ingresa por los anuncios que muestra en ellos (desde 2024).', 'Los canales de WhatsApp también permiten difundir novedades; los mensajes llegan a quien se une voluntariamente.', 'Las comunidades de pago dan contenido exclusivo por una cuota mensual.', 'Nunca se añade a nadie sin permiso ni se comparten sus datos: además de molesto, lo prohíben las leyes de protección de datos.'], ['canal', 'grupo', 'suscriptor', 'comunidad de pago', 'permiso'], 'V:Un canal difunde a muchas personas a la vez.|F:Se puede añadir a cualquiera sin permiso.|V:Telegram reparte el 50 % de los anuncios en canales grandes.', ['Crea el plan de un canal: nombre, tema y frecuencia.', 'Calcula los ingresos de una comunidad de pago.'], { t: 'flujo', p: ['crear canal', 'describir', 'invitar', 'publicar', 'monetizar'] }, '¿Por qué un canal propio es más seguro que depender del algoritmo?', ['rs_pasos:tg']);
  un('rs_anuncios', 'Ingresos por anuncios y programas de creadores', 'redes_yt', ['El CPM es lo que paga el anunciante por mil impresiones; el RPM, lo que recibe el creador por cada mil vistas.', 'YouTube entrega a los creadores el 55 % de los ingresos por anuncios en vídeos largos y el 45 % en Shorts.', 'Para entrar en su Programa de Socios hacen falta 1.000 suscriptores y 4.000 horas de visualización en 12 meses, o 10 millones de vistas de Shorts en 90 días.', 'El RPM cambia mucho según el país del público, el tema y la época del año: finanzas paga más que humor, y diciembre más que enero.', 'Con anuncios hacen falta muchas vistas para ingresos modestos; por eso casi nadie vive solo de ellos.'], ['CPM', 'RPM', 'Programa de Socios', 'reparto', 'visualizaciones'], 'V:El RPM es lo que recibe el creador por mil vistas.|F:YouTube entrega el 100 % de los anuncios.|V:El RPM depende del país y del tema.', ['¿Qué diferencia hay entre CPM y RPM?', 'Calcula cuántas vistas harían falta para ganar el salario mínimo.'], { t: 'flujo', p: ['anunciante paga', 'plataforma cobra', 'reparto', 'creador recibe', 'impuestos'] }, '¿Cuántas vistas necesitarías para pagar el alquiler?', ['rs_calc']);
  un('rs_afiliados', 'Afiliación: comisiones por venta', 'redes_com', ['En la afiliación recomiendas un producto con un enlace propio y cobras una comisión cuando alguien compra.', 'Las comisiones dependen de la tienda y la categoría: en las grandes tiendas en línea suelen ir de un pequeño porcentaje a alrededor del 10 %.', 'Lo que se gana es clics × tasa de conversión × precio × comisión: pocas ventas en un nicho caro pueden valer más que muchas baratas.', 'Solo se recomienda lo que se ha probado o investigado: la confianza es el capital del creador.', 'La ley obliga a avisar de que el enlace es de afiliado.'], ['enlace de afiliado', 'comisión', 'conversión', 'cookie', 'aviso'], 'V:Hay que avisar de que el enlace es de afiliado.|F:La comisión es igual en todas las categorías.|V:Se cobra cuando alguien compra.', ['Calcula la comisión de un mes con tus propios datos.', '¿Qué producto de tu nicho recomendarías y por qué?'], { t: 'flujo', p: ['elegir producto', 'crear enlace', 'publicar con aviso', 'clic', 'comisión'] }, '¿Cuántas cosas has comprado por la recomendación de alguien?', ['rs_pasos:afiliado']);
  un('rs_marcas', 'Colaboraciones con marcas y contenido UGC', 'redes_ugc', ['Una marca paga por publicar su producto en tu cuenta (patrocinio) o por vídeos que ella publicará en la suya (UGC).', 'Para el UGC no hacen falta muchos seguidores: la marca paga por la calidad del vídeo, no por tu audiencia.', 'El kit de medios resume quién eres, tu público, tus números y tus tarifas.', 'Una propuesta clara incluye entregables, fechas, derechos de uso, número de cambios y forma de pago.', 'Todo acuerdo se firma por escrito y se cobra, al menos en parte, por adelantado.'], ['patrocinio', 'UGC', 'kit de medios', 'derechos de uso', 'tarifa'], 'V:El UGC no exige muchos seguidores.|F:Los acuerdos con marcas no necesitan contrato.|V:El kit de medios resume tus números.', ['Prepara tu kit de medios.', 'Calcula tus ingresos con UGC en un mes.'], { t: 'flujo', p: ['kit de medios', 'propuesta', 'contrato', 'entrega', 'cobro'] }, '¿Por qué una marca pagaría por un vídeo que no se publica en tu cuenta?', ['rs_kit']);
  un('rs_productos', 'Vender productos y servicios propios', 'redes_sus', ['Con un producto propio te quedas con casi todo el margen: guías, plantillas, cursos, recetarios o productos físicos.', 'Los servicios (clases, asesorías, gestión de redes) se pueden vender desde el primer día y validan qué necesita el público.', 'Las suscripciones dan un ingreso mensual previsible; la plataforma suele quedarse una comisión.', 'La escalera de valor ofrece algo gratis, algo barato y algo completo, para que cada persona elija su paso.', 'Con pocos seguidores fieles se puede ganar más que con muchos que solo miran.'], ['producto digital', 'servicio', 'suscripción', 'escalera de valor', 'margen'], 'V:Un servicio se puede vender desde el primer día.|F:Hacen falta millones de seguidores para vender.|V:La suscripción da ingresos previsibles.', ['Diseña tu escalera de valor con tres escalones.', 'Calcula los ingresos netos de una suscripción.'], { t: 'flujo', p: ['gratis', 'barato', 'completo', 'suscripción', 'recomendación'] }, '¿Qué sabes hacer por lo que alguien te pagaría hoy?', ['rs_ingresos']);
  un('rs_metricas', 'Métricas que importan', 'redes_engalc', ['El alcance es cuántas personas distintas vieron la publicación; las impresiones, cuántas veces se mostró.', 'La tasa de interacción suma me gusta, comentarios, compartidos y guardados, y la divide entre seguidores o entre alcance.', 'La retención dice qué parte del vídeo se ve: si la gente se va en el segundo 2, falla el gancho.', 'Los clics en el enlace y las ventas son las métricas que pagan las facturas.', 'Se revisan una vez por semana y se cambia una sola cosa cada vez para saber qué funcionó.'], ['alcance', 'impresiones', 'tasa de interacción', 'retención', 'clic en el enlace'], 'V:El alcance cuenta personas distintas.|F:Las impresiones y el alcance son lo mismo.|V:Se cambia una cosa cada vez.', ['Calcula la tasa de interacción por alcance de tres publicaciones.', 'Diseña tu hoja semanal de métricas.'], { t: 'ciclo', p: ['medir', 'comparar', 'decidir', 'cambiar una cosa', 'medir'] }, '¿Cómo sabrías qué vídeo te trajo más clientes?', ['rs_pasos:metricas']);
  un('rs_legal', 'Aspectos legales, impuestos y plan de 90 días', 'redes_imp', ['La publicidad debe identificarse siempre: «publicidad», «colaboración pagada» o la etiqueta de la plataforma.', 'Los ingresos de las redes son ingresos gravables: hay que declararlos y, según el país, darse de alta como autónomo o en un régimen simplificado.', 'Las imágenes, músicas y textos de otros tienen derechos de autor: se usan las bibliotecas autorizadas de cada plataforma.', 'Los datos de seguidores y clientes se tratan con permiso y se guardan con cuidado.', 'Un plan de 90 días con metas medibles convierte la teoría en ingresos reales.'], ['publicidad identificada', 'impuestos', 'derechos de autor', 'protección de datos', 'plan de 90 días'], 'V:La publicidad debe identificarse.|F:Lo que se gana en redes no paga impuestos.|V:La música de otros tiene derechos.', ['Escribe cómo avisarías de una colaboración pagada.', 'Diseña tu plan de 90 días.'], { t: 'flujo', p: ['avisar publicidad', 'declarar ingresos', 'respetar derechos', 'proteger datos', 'plan'] }, '¿Qué pasa si una marca te paga y no lo dices?', ['rs_legal', 'rs_plan90']);

  /* ─────────── generadores ─────────── */
  var NICHOS = ['recetas rápidas', 'finanzas personales', 'manualidades', 'viajes baratos', 'ejercicio en casa', 'tecnología', 'maquillaje', 'jardinería', 'idiomas', 'mascotas'];
  var GEN = {
    redes_eng: function (u, C, r) { var s = P(r, [1200, 2500, 4000, 8000, 15000]), mg = Math.round(s * P(r, [2, 3, 4, 5]) / 100), co = Math.round(mg * P(r, [.05, .08, .1])), cp = Math.round(mg * P(r, [.03, .05])), gu = Math.round(mg * P(r, [.06, .1])), t = mg + co + cp + gu; return it('corta', 'Una cuenta de ' + P(r, NICHOS) + ' tiene ' + n(s, C) + ' seguidores. Una publicación recibió ' + mg + ' me gusta, ' + co + ' comentarios, ' + cp + ' compartidos y ' + gu + ' guardados. ¿Cuál es su tasa de interacción por seguidores?', n(pc(t, s), C) + ' %', { ac: [pc(t, s)], x: 'Interacciones = ' + mg + ' + ' + co + ' + ' + cp + ' + ' + gu + ' = ' + t + '. Tasa = ' + t + ' ÷ ' + n(s, C) + ' × 100 = ' + n(pc(t, s), C) + ' %.' }); },
    redes_engalc: function (u, C, r) { var a = P(r, [3000, 6000, 9000, 20000]), t = Math.round(a * P(r, [3, 4.5, 6, 8]) / 100); return it('corta', 'Un vídeo llegó a ' + n(a, C) + ' personas (alcance) y sumó ' + n(t, C) + ' interacciones. ¿Cuál es la tasa de interacción por alcance?', n(pc(t, a), C) + ' %', { ac: [pc(t, a)], x: 'Tasa por alcance = interacciones ÷ alcance × 100 = ' + n(t, C) + ' ÷ ' + n(a, C) + ' × 100 = ' + n(pc(t, a), C) + ' %.' }); },
    redes_cpm: function (u, C, r) { var v = P(r, [50000, 120000, 200000, 400000]), rpm = r2(m(P(r, [.3, .5, .8, 1.2]), C)), g = r2(v / 1000 * rpm); return it('corta', 'Un vídeo largo tuvo ' + n(v, C) + ' visualizaciones cualificadas. Si el RPM de ejemplo es ' + $(rpm, C) + ' por mil vistas, ¿cuánto se gana?', $(g, C), { ac: [g, n(g, C)], x: 'Ingreso = vistas ÷ 1000 × RPM = ' + n(v, C) + ' ÷ 1000 × ' + $(rpm, C) + ' = ' + $(g, C) + '. Es un RPM de ejemplo: la plataforma no publica una tarifa fija.' }); },
    redes_yt: function (u, C, r) { var a = m(P(r, [200, 400, 600, 1000]), C), sh = r() < .35, k = sh ? 45 : 55, g = r2(a * k / 100); return it('corta', 'Los anuncios de tus ' + (sh ? 'Shorts' : 'vídeos largos') + ' generaron ' + $(a, C) + ' en un mes. YouTube entrega al creador el ' + k + ' %. ¿Cuánto recibes?', $(g, C), { ac: [g, n(g, C)], x: 'Parte del creador = ' + $(a, C) + ' × ' + k + ' ÷ 100 = ' + $(g, C) + ' (YouTube: 55 % en vídeos largos, 45 % en Shorts).' }); },
    redes_tg: function (u, C, r) { var a = m(P(r, [40, 80, 150, 300]), C), g = r2(a / 2); return it('corta', 'Telegram ingresó ' + $(a, C) + ' por los anuncios que mostró en tu canal este mes. Si reparte el 50 % con el propietario, ¿cuánto te corresponde?', $(g, C), { ac: [g, n(g, C)], x: '50 % de ' + $(a, C) + ' = ' + $(a, C) + ' ÷ 2 = ' + $(g, C) + '. Solo aplica a canales públicos con al menos 1.000 suscriptores.' }); },
    redes_com: function (u, C, r) { var cl = P(r, [800, 1500, 3000, 5000]), cv = P(r, [1, 1.5, 2, 3]), pr = m(P(r, [25, 40, 60, 120]), C), k = P(r, [3, 4, 6, 8, 10]), vt = Math.round(cl * cv / 100), g = r2(vt * pr * k / 100); return it('corta', 'Tu enlace de afiliado recibió ' + n(cl, C) + ' clics; el ' + n(cv, C) + ' % compró un producto de ' + $(pr, C) + ' con una comisión del ' + k + ' %. ¿Cuánto ganas?', $(g, C), { ac: [g, n(g, C)], x: 'Ventas = ' + n(cl, C) + ' × ' + n(cv, C) + ' % = ' + vt + '. Comisión = ' + vt + ' × ' + $(pr, C) + ' × ' + k + ' % = ' + $(g, C) + '.' }); },
    redes_ugc: function (u, C, r) { var v = P(r, [4, 6, 8, 10, 12]), t = m(P(r, [60, 90, 120, 150]), C), h = m(P(r, [20, 30, 50]), C), g = v * t - h; return it('corta', 'Este mes entregas ' + v + ' vídeos UGC a ' + $(t, C) + ' cada uno. Tus gastos (atrezo, apps, internet) son ' + $(h, C) + '. ¿Cuánto ganas?', $(g, C), { ac: [g, n(g, C)], x: 'Ganancia = vídeos × tarifa − gastos = ' + v + ' × ' + $(t, C) + ' − ' + $(h, C) + ' = ' + $(g, C) + '.' }); },
    redes_sus: function (u, C, r) { var s = P(r, [40, 80, 120, 200]), p = m(P(r, [3, 5, 8]), C), k = P(r, [10, 20, 30]), g = r2(s * p * (100 - k) / 100); return it('corta', 'Tienes ' + s + ' suscriptores que pagan ' + $(p, C) + ' al mes. La plataforma se queda el ' + k + ' %. ¿Cuánto ingresas neto al mes?', $(g, C), { ac: [g, n(g, C)], x: 'Neto = ' + s + ' × ' + $(p, C) + ' × (100 − ' + k + ') ÷ 100 = ' + $(g, C) + '.' }); },
    redes_crec: function (u, C, r) { var s = P(r, [500, 1000, 2000, 3000]), g = P(r, [10, 15, 20]), me = 3, f = Math.round(s * Math.pow(1 + g / 100, me)); return it('corta', 'Una cuenta empieza con ' + n(s, C) + ' seguidores y crece un ' + g + ' % cada mes. ¿Cuántos tendrá dentro de ' + me + ' meses?', n(f, C), { ac: [f], x: n(s, C) + ' × ' + n(1 + g / 100, C) + '³ = ' + n(f, C) + ' (el crecimiento se acumula mes a mes).' }); },
    redes_conv: function (u, C, r) { var v = P(r, [2000, 5000, 8000]), cl = Math.round(v * P(r, [1, 2, 3]) / 100), ve = Math.max(1, Math.round(cl * P(r, [3, 5, 8]) / 100)); return it('corta', 'Tu publicación en Marketplace tuvo ' + n(v, C) + ' vistas, ' + cl + ' mensajes y ' + ve + ' ventas. ¿Qué porcentaje de los mensajes terminó en venta?', n(pc(ve, cl), C) + ' %', { ac: [pc(ve, cl)], x: 'Conversión = ventas ÷ mensajes × 100 = ' + ve + ' ÷ ' + cl + ' × 100 = ' + n(pc(ve, cl), C) + ' %.' }); },
    redes_hora: function (u, C, r) { var g = m(P(r, [300, 450, 600, 900]), C), h = P(r, [30, 40, 60, 80]), v = r2(g / h); return it('corta', 'En un mes ganaste ' + $(g, C) + ' con tus redes y dedicaste ' + h + ' horas a grabar, editar y responder. ¿Cuánto ganaste por hora?', $(v, C), { ac: [v, n(v, C)], x: 'Valor de la hora = ingresos ÷ horas = ' + $(g, C) + ' ÷ ' + h + ' = ' + $(v, C) + '. Compáralo con el salario mínimo por hora de tu país.' }); },
    redes_imp: function (u, C, r) { var g = m(P(r, [400, 800, 1200, 2000]), C), k = P(r, [15, 20, 25]), v = r2(g * k / 100); return it('corta', 'Este mes ingresaste ' + $(g, C) + ' por redes. Si apartas un ' + k + ' % para impuestos, ¿cuánto guardas?', $(v, C), { ac: [v, n(v, C)], x: g + ' × ' + k + ' ÷ 100 = ' + $(v, C) + '. El porcentaje real depende del país y de tu régimen: consulta la administración tributaria.' }); }
  };

